CREATE OR REPLACE FUNCTION public.rs_resource_tenant(p_table text, p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
        DECLARE result uuid;
        BEGIN
            IF p_table NOT IN ('users', 'cameras', 'alerts', 'evidence', 'approval_requests', 'user_sessions', 'invitations', 'service_accounts', 'camera_source_grants', 'camera_config_versions', 'camera_worker_status', 'camera_health_events', 'case_notes', 'case_note_revisions', 'case_bookmarks', 'export_jobs', 'saved_searches', 'case_links', 'case_followups', 'case_followup_events', 'case_legal_holds') THEN
                RAISE EXCEPTION 'table not allowed';
            END IF;
            EXECUTE format('SELECT tenant_id FROM %I WHERE id = $1', p_table)
                INTO result USING p_id;
            RETURN result;
        END $function$
